using FluentAssertions; using Sigov.Domain.Agro; using Sigov.Domain.Agro.Enums; using Xunit;
namespace Sigov.UnitTests.Agro; public sealed class AgroEstradaVicinalRulesTests{[Fact] public void Estrada_exige_codigo()=>FluentActions.Invoking(()=>new EstradaVicinal(1,1,"","Nome",AgroEstradaSituacao.BOA)).Should().Throw<ArgumentException>(); [Fact] public void Estrada_exige_nome()=>FluentActions.Invoking(()=>new EstradaVicinal(1,1,"E1","",AgroEstradaSituacao.BOA)).Should().Throw<ArgumentException>(); [Fact] public void Extensao_negativa_falha()=>FluentActions.Invoking(()=>new EstradaVicinal(1,1,"E1","Nome",AgroEstradaSituacao.BOA,-1)).Should().Throw<ArgumentException>(); [Fact] public void Coordenada_invalida_falha()=>FluentActions.Invoking(()=>new EstradaVicinal(1,1,"E1","Nome",AgroEstradaSituacao.BOA,null,100,10)).Should().Throw<ArgumentException>();}
